import { ProductInfoStyle } from './index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { DisplayFlexCCC, Row } from '../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../lang/index'
import { formatMoney } from '../../../../../helpers/utility'

function ProductConfirmationDetailHeader ({ policy }) {
  const renderItemAmount = (text, subText, textAlign) => {
    return (
      <div>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size='0.6em'
          weight={700}
          className='text-uppercase'
        >
          {text}
        </CustomText>
        <CustomText
          color={AgentColorPallette.dodgerBlue}
          size='0.8em'
          weight={700}
          textAlign={textAlign}
        >
          {subText}
        </CustomText>
      </div>
    )
  }

  return (
    <ProductInfoStyle>
      <DisplayFlexCCC>
        <img src={policy?.policy_details?.package_data?.provider?.logo_url} width={48} alt='icon' />
        <CustomText
          size='0.75em'
          top='15px'
          color={AgentColorPallette.fontDarkerGrey}
        >
          {policy?.policy_details?.package_data?.name}
        </CustomText>
        <CustomText
          size='1em'
          weight={700}
          bottom='0.8rem'
          color={AgentColorPallette.blackGrey}
        >
          {`${policy?.policy_details?.customer_data?.name} / ${policy?.policy_details?.region_code} ${policy?.policy_details?.vehicle_plate_no}`}
        </CustomText>
      </DisplayFlexCCC>
      {
        <Row align='center' justify='space-between' className='status-yellow'>
          <CustomText
            size='0.75em'
            weight={700}
            color={AgentColorPallette.goldYellow}
            bottom='0'
          >
            Status Pesanan
          </CustomText>
          <CustomText
            size='0.75em'
            weight={700}
            color={AgentColorPallette.goldYellow}
            bottom='0'
          >
            {LANG_STRINGS.waitingForPayment}
          </CustomText>
        </Row>
      }
      {
        policy?.application_no && (
          <Row align='center' justify='space-between' className='policy-number'>
            <CustomText
              size='0.75em'
              weight={700}
              color={AgentColorPallette.darkCyanBlue}
              bottom='0'
            >
              Polis ID
            </CustomText>
            <CustomText
              size='0.75em'
              weight={700}
              color={AgentColorPallette.darkCyanBlue}
              bottom='0'
            >
              {policy?.application_no}
            </CustomText>
          </Row>
        )
      }
      {
        policy?.insurance_details?.insurance_policy_no && (
          <Row align='center' justify='space-between' className='policy-number'>
            <CustomText
              size='0.75em'
              weight={700}
              color={AgentColorPallette.darkCyanBlue}
              bottom='0'
            >
              No. Polis Asuransi
            </CustomText>
            <CustomText
              size='0.75em'
              weight={700}
              color={AgentColorPallette.darkCyanBlue}
              bottom='0'
            >
              {policy?.insurance_details?.insurance_policy_no}
            </CustomText>
          </Row>
        )
      }
      {
        (policy?.policy_status === 'ACTIVE' || policy?.policy_status === 'POLICY_CREATED' || policy?.policy_status === 'EXPIRED') && (
          <Row align='center' justify='space-between' className={policy?.policy_status === 'EXPIRED' ? 'status-grey' : 'status-green'}>
            <CustomText
              size='0.75em'
              weight={700}
              color={policy?.policy_status === 'EXPIRED' ? AgentColorPallette.fontGrey : AgentColorPallette.irishGreen}
              bottom='0'
            >
              Status Polis
            </CustomText>
            <CustomText
              size='0.75em'
              weight={700}
              color={policy?.policy_status === 'EXPIRED' ? AgentColorPallette.fontGrey : AgentColorPallette.irishGreen}
              bottom='0'
            >
              {policy?.policy_status === 'EXPIRED' ? 'Berakhir' : 'Aktif'}
            </CustomText>
          </Row>
        )
      }
      <div className='pkg-item-btm'>
        {
          <Row justify='space-between' align='center'>
            {
              renderItemAmount(
                'Premi / 12 Bulan',
                formatMoney((policy?.policy_details?.package_data?.basic_premium), 0)
              )
            }
            {
              renderItemAmount(
                LANG_STRINGS.valueOfCoverage,
                formatMoney((policy?.policy_details?.package_data?.total_sum_insured), 0), 'right'
              )
            }
          </Row>
        }
      </div>
    </ProductInfoStyle>
  )
}

export default ProductConfirmationDetailHeader
